SELECT 'delivery_disabled' AS check_name,CASE WHEN count(*)=1 AND bool_and(NOT enabled AND activated_at IS NULL) THEN 'READY' ELSE 'FAIL' END AS status FROM public.hq_review_sms_delivery_state
UNION ALL SELECT 'no_backfill',CASE WHEN count(*)=0 THEN 'READY' ELSE 'FAIL' END FROM public.hq_review_sms_outbox
UNION ALL SELECT 'three_insert_triggers',CASE WHEN count(*)=3 THEN 'READY' ELSE 'FAIL' END FROM pg_trigger WHERE tgname IN ('enqueue_purchase_review_sms','enqueue_recharge_review_sms','enqueue_verification_review_sms') AND NOT tgisinternal AND tgenabled='O'
UNION ALL SELECT 'rls_enabled',CASE WHEN count(*)=2 AND bool_and(relrowsecurity) THEN 'READY' ELSE 'FAIL' END FROM pg_class WHERE oid IN ('public.hq_review_sms_outbox'::regclass,'public.hq_review_sms_delivery_state'::regclass)
UNION ALL SELECT 'client_functions_denied',CASE WHEN NOT has_function_privilege('anon','public.claim_hq_review_sms_v96(text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.start_hq_review_sms_v96(bigint,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.finish_hq_review_sms_v96(bigint,text,text,text,text,text)','EXECUTE') THEN 'READY' ELSE 'FAIL' END
UNION ALL SELECT 'client_tables_denied',CASE WHEN NOT has_table_privilege('anon','public.hq_review_sms_outbox','SELECT') AND NOT has_table_privilege('authenticated','public.hq_review_sms_delivery_state','UPDATE') THEN 'READY' ELSE 'FAIL' END;
